FIELDS=("type","value_type","units","preprocessing")

def analyze_template_link(existing_items,incoming_items,trigger_refs):
    if not all(isinstance(rows,list) for rows in (existing_items,incoming_items,trigger_refs)):
        raise ValueError("inputs must be lists")
    def index(rows,label):
        result={}
        for item in rows:
            if not isinstance(item,dict) or not all(isinstance(item.get(k),str) and item[k] for k in ("id","key","source")):
                raise ValueError("item id/key/source required")
            result.setdefault(item["key"],[]).append(item)
        if any(len(items)>1 for items in result.values()):raise ValueError(label+" contains duplicate keys")
        return result
    existing=index(existing_items,"existing items");incoming=index(incoming_items,"incoming template")
    refs={}
    for row in trigger_refs:
        if not isinstance(row,dict) or not row.get("key") or not row.get("trigger"):
            raise ValueError("trigger key and id required")
        refs.setdefault(row["key"],[]).append(row["trigger"])
    conflicts=[]
    for key,item_list in incoming.items():
        old=existing.get(key)
        if not old:continue
        before,after=old[0],item_list[0]
        differences=[field for field in FIELDS if before.get(field)!=after.get(field)]
        conflicts.append({"key":key,"kind":"semantic_conflict" if differences else "identical_definition",
            "existing_id":before["id"],"existing_source":before["source"],
            "incoming_id":after["id"],"incoming_source":after["source"],
            "different_fields":differences,"referenced_by":sorted(refs.get(key,[])),
            "action":"reconcile the authoritative item and its references before linking; do not rename or delete automatically"})
    return {"link_ready":not conflicts,"conflicts":conflicts}
```

